INSERT OR REPLACE INTO ec_page_home ("id", "slug", "status", "created_at", "updated_at", "published_at", "version", "locale", "translation_group", "seo_title", "seo_description", "hero_heading", "hero_heading_accent", "hero_positioning", "hero_proof_before", "hero_proof_link_text", "hero_proof_after", "hero_primary_label", "hero_secondary_label", "work_heading", "work_sub", "work_link_label", "pricing_heading", "pricing_sub", "pricing_includes_lead", "pricing_includes", "pricing_reassurance", "pricing_link_label", "process_heading", "process_sub", "process_steps", "process_cta_title", "process_cta_sub", "process_cta_label") VALUES ('01CI54FB38483C50730883EF1E', 'home', 'published', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', '2026-10-03T00:00:00.000Z', 1, 'en', '01CI54FB38483C50730883EF1E', 'Nixon Creative Studio | Strategy-led design and photography', 'Modern websites for small businesses, nonprofits, churches, and schools. Based in Cincinnati, working with clients anywhere.', 'I make websites that', 'pull their weight.', 'For churches, schools, nonprofits, and small businesses, wherever you are.', 'Based in Cincinnati. Every site designed, built, and photographed by', 'one person', ', start to finish.', 'Start a project', 'See the work', 'Selected work', 'A few recent projects. Each one started with a conversation about what the organization actually needed, not which template to pick.', 'Explore more projects', 'What it costs', 'Honest from the first conversation, so you can size up the fit before we ever talk.', 'Every build includes, whatever the tier:', '[{"text":"A custom design, yours to keep"},{"text":"100 / 100 accessibility"},{"text":"Strategy and a content system, included"},{"text":"One person, start to finish"}]', 'Every number is a starting point. The first conversation is free and ends with an honest ballpark, and larger projects can split into monthly payments.', 'See full pricing and services', 'How we work', 'Four steps, from the first conversation to launch day.', '[{"title":"Conversation","body":"We meet for an hour, in person or on video, and talk about what you actually need. No pitch deck, no agency theater. Just a working session that ends with a one-page brief we both agree on."},{"title":"Strategy","body":"I write the audience map, the page architecture, and the conversion path. You read it, push back, we revise. The strategy doc is the source of truth for every design choice that follows."},{"title":"Design and build","body":"Components, content, and pages built in the open. Preview links land in your inbox at every milestone so you can react early instead of seeing the whole thing for the first time at launch."},{"title":"Launch and follow-through","body":"We go live together, then I stay close for the first month to fix anything that surfaces. After that you own the site outright, with documentation and a simple way to reach me when something comes up."}]', 'Tell me what you are building.', 'I take a small number of projects each quarter. The earlier we talk, the better we can pace it together.', 'Start a project');
